// SystemEscape leaves the authorized path. It returns the unrestricted
// system clients for the caller transaction itself, so their reads and
// writes run inside that transaction and commit or roll back with every
// caller write in it.
//
// Nothing performed through them is policy-checked. No caller rule, field
// restriction, or row predicate applies, exactly as if the write had been
// made by App.System. Use it only for a value the application owns and no
// client may set, and keep the call at the site that needs it: every call
// is observed as transaction.system_escape.
func SystemEscape[P any](transaction *CallerTx[P]) *SystemTx[P] {
	var inner *golemruntime.SystemTx[P, Actor]
	if transaction != nil {
		inner = golemruntime.CallerTxSystem(transaction.runtime)
	}
	result := &SystemTx[P]{runtime: inner}
	result.Documents = SystemTxDocumentClient[P]{runtime: inner}
	return result
}

func (system System[P]) Transaction(ctx context.Context, callback func(*SystemTx[P]) error, options ...golem.TransactionOption) error {
	if callback == nil {
		return golemruntime.SystemTransaction(ctx, system.runtime, nil, options...)
	}
	return golemruntime.SystemTransaction(ctx, system.runtime, func(inner *golemruntime.SystemTx[P, Actor]) error {
		result := &SystemTx[P]{runtime: inner}
		result.Documents = SystemTxDocumentClient[P]{runtime: inner}
		return callback(result)
	}, options...)
}

func OnJobFailed[P, T any](jobType queue.Type[T], callback func(context.Context, *SystemTx[P], queue.Failure[T]) error) golemruntime.JobFailed[P, Actor] {
	if callback == nil {
		return golemruntime.OnJobFailed[P, Actor, T](jobType, nil)
	}
	return golemruntime.OnJobFailed(jobType, func(ctx context.Context, inner *golemruntime.SystemTx[P, Actor], failure queue.Failure[T]) error {
		result := &SystemTx[P]{runtime: inner}
		result.Documents = SystemTxDocumentClient[P]{runtime: inner}
		return callback(ctx, result, failure)
	})
}
func (transaction *SystemTx[P]) Enqueue(ctx context.Context, pending queue.Pending) (queue.JobID, error) {
	if transaction == nil {
		return golemruntime.SystemTxEnqueue(ctx, (*golemruntime.SystemTx[P, Actor])(nil), pending)
	}
	return golemruntime.SystemTxEnqueue(ctx, transaction.runtime, pending)
}
func (transaction *SystemTx[P]) CancelJob(ctx context.Context, id queue.JobID) (bool, error) {
	if transaction == nil {
		return golemruntime.SystemTxCancelJob(ctx, (*golemruntime.SystemTx[P, Actor])(nil), id)
	}
	return golemruntime.SystemTxCancelJob(ctx, transaction.runtime, id)
}
func (transaction *SystemTx[P]) PromoteJob(ctx context.Context, id queue.JobID, priority queue.Priority, options ...queue.PromotionOption) (bool, error) {
	if transaction == nil {
		return golemruntime.SystemTxPromoteJob(ctx, (*golemruntime.SystemTx[P, Actor])(nil), id, priority, options...)
	}
	return golemruntime.SystemTxPromoteJob(ctx, transaction.runtime, id, priority, options...)
}
func (transaction *SystemTx[P]) LockKeys(ctx context.Context, keys ...golem.LockKey) error {
	if transaction == nil {
		return golemruntime.SystemTxLockKeys(ctx, (*golemruntime.SystemTx[P, Actor])(nil), keys...)
	}
	return golemruntime.SystemTxLockKeys(ctx, transaction.runtime, keys...)
}
